import json
import subprocess
from pathlib import Path

SUBMISSIONS_ROOT = Path("/srv/lms/submissions")
GRADERS_ROOT = Path("/srv/lms/graders")


def run_assignment_autograder(course_code, assignment_slug, submission_id, timeout_seconds=300):
    submission_directory = SUBMISSIONS_ROOT / course_code / assignment_slug / submission_id
    grader_directory = GRADERS_ROOT / course_code / assignment_slug
    if not submission_directory.is_dir():
        return {"error": f"Submission {submission_id} not found for {course_code}/{assignment_slug}"}
    if not grader_directory.is_dir():
        return {"error": f"No autograder configured for {course_code}/{assignment_slug}"}
    container_command = [
        "docker", "run", "--rm", "--network", "none", "--memory", "512m",
        "-v", f"{submission_directory}:/submission:ro",
        "-v", f"{grader_directory}:/grader:ro",
        "lms-autograder:latest", "python", "/grader/run_tests.py", "--json", "/submission",
    ]
    try:
        completed_grader_process = subprocess.run(
            container_command, capture_output=True, text=True, timeout=timeout_seconds
        )
    except subprocess.TimeoutExpired:
        return {"submission_id": submission_id, "status": "timeout", "timeout_seconds": timeout_seconds}
    try:
        parsed_test_results = json.loads(completed_grader_process.stdout)
    except json.JSONDecodeError:
        parsed_test_results = None
    return {
        "submission_id": submission_id,
        "status": "completed" if completed_grader_process.returncode == 0 else "grader_error",
        "exit_code": completed_grader_process.returncode,
        "results": parsed_test_results,
        "stderr_tail": completed_grader_process.stderr[-2000:],
    }

import sqlite3

DB_PATH = "/srv/lms/lms.db"


def delete_discussion_thread(course_id, thread_id):
    database_connection = sqlite3.connect(DB_PATH)
    try:
        database_cursor = database_connection.cursor()
        matching_thread_row = database_cursor.execute(
            "SELECT title FROM discussion_threads WHERE id = ? AND course_id = ?",
            (thread_id, course_id),
        ).fetchone()
        if matching_thread_row is None:
            return {"deleted": False, "reason": f"Thread {thread_id} not found in course {course_id}"}
        deleted_reaction_count = database_cursor.execute(
            "DELETE FROM post_reactions WHERE post_id IN (SELECT id FROM discussion_posts WHERE thread_id = ?)",
            (thread_id,),
        ).rowcount
        deleted_reply_count = database_cursor.execute(
            "DELETE FROM discussion_posts WHERE thread_id = ?", (thread_id,)
        ).rowcount
        database_cursor.execute("DELETE FROM discussion_threads WHERE id = ?", (thread_id,))
        database_connection.commit()
    except sqlite3.Error as database_error:
        database_connection.rollback()
        return {"deleted": False, "reason": str(database_error)}
    finally:
        database_connection.close()
    return {
        "deleted": True,
        "thread_id": thread_id,
        "title": matching_thread_row[0],
        "replies_deleted": deleted_reply_count,
        "reactions_deleted": deleted_reaction_count,
    }
